function validate([pattern, s]) {
  if (pattern.length < 1 || pattern.length > 20) return 'pattern needs 1 to 20 letters.';
  if (s.length < 1 || s.length > 20) return 's needs 1 to 20 letters.';
  if (!/^[a-z]+$/.test(pattern) || !/^[a-z]+$/.test(s)) return 'Use only lowercase English letters.';
  return null;
}

