function wordPatternMatch(pattern, s) {
  const mapping = new Map();
  const used = new Set();

  function match(i, j) {
    if (i === pattern.length) {
      return j === s.length;
    }
    const letter = pattern[i];
    if (mapping.has(letter)) {
      const word = mapping.get(letter);
      if (!s.startsWith(word, j)) {
        return false;
      }
      return match(i + 1, j + word.length);
    }
    const lettersLeft = pattern.length - i - 1;
    for (let end = j + 1; end <= s.length - lettersLeft; end++) {
      const word = s.slice(j, end);
      if (used.has(word)) {
        continue;
      }
      mapping.set(letter, word);
      used.add(word);
      if (match(i + 1, end)) {
        return true;
      }
      mapping.delete(letter);
      used.delete(word);
    }
    return false;
  }

  return match(0, 0);
}

