function wordPatternMatch(pattern, s) {
  // Try every way to cut s into pattern.length non-empty pieces, then test the letter-piece pairing.
  const k = pattern.length;
  const n = s.length;
  if (k > n) return false;
  const cuts = [];
  function pairsUp() {
    const forward = new Map();
    const backward = new Map();
    let start = 0;
    for (let i = 0; i < k; i++) {
      const piece = s.slice(start, cuts[i]);
      start = cuts[i];
      if (!forward.has(pattern[i]) && !backward.has(piece)) {
        forward.set(pattern[i], piece);
        backward.set(piece, pattern[i]);
      } else if (forward.get(pattern[i]) !== piece || backward.get(piece) !== pattern[i]) {
        return false;
      }
    }
    return true;
  }
  function cut(start, count) {
    if (count === k - 1) {
      cuts.push(n);
      const ok = pairsUp();
      cuts.pop();
      return ok;
    }
    for (let end = start + 1; end <= n - (k - 1 - count); end++) {
      cuts.push(end);
      if (cut(end, count + 1)) return true;
      cuts.pop();
    }
    return false;
  }
  return cut(0, 0);
}

