function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomString = (length, alphabet) => Array.from({ length }, () => alphabet[pick(alphabet.length)]).join('');
  const large = size === 'large';
  const patternLength = large ? 6 + pick(10) : 1 + pick(6);
  const pattern = randomString(patternLength, letters.slice(0, large ? 2 + pick(5) : 1 + pick(3)));
  const alphabet = letters.slice(0, 1 + pick(large ? 3 : 2));
  if (rand() < 0.5) {
    // Spell s from a random assignment so that matches are common; sometimes change one letter.
    for (let attempt = 0; attempt < 50; attempt++) {
      const words = new Map();
      for (const letter of pattern) if (!words.has(letter)) words.set(letter, randomString(1 + pick(3), alphabet));
      let s = [...pattern].map(letter => words.get(letter)).join('');
      if (s.length > 20) continue;
      if (rand() < 0.3) {
        const at = pick(s.length);
        s = s.slice(0, at) + letters[pick(3)] + s.slice(at + 1);
      }
      return [pattern, s];
    }
  }
  return [pattern, randomString(1 + pick(large ? 20 : 10), alphabet)];
}
